#!/usr/bin/env node
// Ad-hoc contract check against the built app. Not part of the deliverable.
import { spawn } from 'node:child_process';
import path from 'node:path';
import { chromium } from '@playwright/test';

const dir = import.meta.dirname;
const port = 4900 + Math.floor(Math.random() * 90);
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 400));
const base = `http://127.0.0.1:${port}/`;

let pass = 0;
const fails = [];
const ok = (name, cond, extra = '') => (cond ? pass++ : fails.push(`${name}${extra ? ` — ${extra}` : ''}`));

const browser = await chromium.launch();
const ctx = await browser.newContext();
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
page.on('dialog', async (d) => { errors.push('DIALOG: ' + d.message()); await d.dismiss(); });

await page.goto(base, { waitUntil: 'load' });

// --- element contract
ok('form + inputs', await page.$('#note-form #title') && await page.$('#note-form #body') &&
  await page.$('#note-form #avatar') && await page.$('#note-form button[type=submit]'));
ok('search + results-line', !!(await page.$('#search')) && !!(await page.$('p#results-line')));
ok('results-line empty at rest', (await page.textContent('#results-line')) === '');
ok('6 seeded notes', (await page.$$('#feed article.note')).length === 6);
ok('note structure', await page.$('#feed article.note[data-note-id] .note-title') &&
  await page.$('#feed article.note .note-body'));
ok('avatars only where given', (await page.$$('#feed img.note-avatar')).length === 3,
  String((await page.$$('#feed img.note-avatar')).length));

// --- newest first
const order = await page.$$eval('#feed article.note', (n) => n.map((a) => a.dataset.noteId));
ok('newest first', order.join() === '6,5,4,3,2,1', order.join());

// --- rich text renders
ok('bold renders', !!(await page.$('#feed article[data-note-id="1"] .note-body b')));
ok('italic renders', !!(await page.$('#feed article[data-note-id="2"] .note-body i')));
ok('br renders', !!(await page.$('#feed article[data-note-id="3"] .note-body br')));
const href = await page.getAttribute('#feed article[data-note-id="4"] .note-body a', 'href');
ok('link renders + href kept', href === 'https://www.livrarialello.pt/', String(href));

// --- search
await page.fill('#search', 'douro');
await page.waitForTimeout(50);
ok('search filters (case-insensitive)', (await page.$$('#feed article.note')).length === 2,
  String((await page.$$('#feed article.note')).length));
ok('results line text', (await page.textContent('#results-line')) === 'results for "douro"',
  JSON.stringify(await page.textContent('#results-line')));
ok('fragment has q', page.url().endsWith('#q=douro'), page.url());

// --- selection + combined fragment
await page.click('#feed article[data-note-id="5"] .note-title');
await page.waitForTimeout(50);
ok('aria-current set', (await page.getAttribute('#feed article[data-note-id="5"]', 'aria-current')) === 'true');
ok('combined fragment', page.url().endsWith('#q=douro&note=5'), page.url());
ok('only one selected', (await page.$$('#feed article.note[aria-current="true"]')).length === 1);

// --- clearing the query keeps the selection, drops q
await page.fill('#search', '');
await page.waitForTimeout(50);
ok('q dropped from fragment', page.url().endsWith('#note=5'), page.url());
ok('results-line cleared', (await page.textContent('#results-line')) === '');

// --- deep link restore on reload
await page.goto(base + '#q=port&note=3', { waitUntil: 'load' });
await page.waitForTimeout(100);
ok('query restored', (await page.inputValue('#search')) === 'port');
ok('results line restored', (await page.textContent('#results-line')) === 'results for "port"');
ok('selection restored', (await page.getAttribute('#feed article[data-note-id="3"]', 'aria-current')) === 'true');
ok('fragment preserved', page.url().endsWith('#q=port&note=3'), page.url());

// --- hashchange (back/forward, manual edit)
await page.evaluate(() => { location.hash = '#note=2'; });
await page.waitForTimeout(80);
ok('hashchange adopted', (await page.inputValue('#search')) === '' &&
  (await page.getAttribute('#feed article[data-note-id="2"]', 'aria-current')) === 'true');

// --- add a note: clears form, persists, continues the id sequence
await page.goto(base, { waitUntil: 'load' });
await page.fill('#title', 'Cais da Ribeira');
await page.fill('#body', 'Meet at <b>19:00</b>\nby the <a href="https://porto.pt/">river</a>.');
await page.fill('#avatar', 'https://example.test/a.png');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(80);
const first = page.locator('#feed article.note').first();
ok('new note first', (await first.getAttribute('data-note-id')) === '7', await first.getAttribute('data-note-id'));
ok('new note title', (await first.locator('.note-title').textContent()) === 'Cais da Ribeira');
ok('new note bold', !!(await first.locator('.note-body b').count()));
ok('newline became br', (await first.locator('.note-body br').count()) === 1);
ok('new note avatar', (await first.locator('img.note-avatar').getAttribute('src')) === 'https://example.test/a.png');
ok('form cleared', (await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === '' &&
  (await page.inputValue('#avatar')) === '');

await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(100);
ok('persisted across reload', (await page.$$('#feed article.note')).length === 7,
  String((await page.$$('#feed article.note')).length));

// --- injection attempts must not become live markup
const payloads = [
  '<img src=x onerror="window.__pwned=1">',
  '<script>window.__pwned=1<\/script>',
  '<b onclick="window.__pwned=1">click</b>',
  '<a href="javascript:window.__pwned=1">go</a>',
  '<a href="java\tscript:window.__pwned=1">go</a>',
  '<a href="&#106;avascript:window.__pwned=1">go</a>',
  '<b>unclosed',
  '<svg/onload=window.__pwned=1>',
  '<a href="x" onmouseover="window.__pwned=1">y</a>',
  '"><img src=x onerror=window.__pwned=1>',
