await new Promise((r) => setTimeout(r, 400));
const base = `http://127.0.0.1:${port}/`;

let pass = 0;
const fails = [];
const ok = (name, cond, extra = '') => (cond ? pass++ : fails.push(`${name}${extra ? ` — ${extra}` : ''}`));

const browser = await chromium.launch();
const ctx = await browser.newContext();
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
page.on('dialog', async (d) => { errors.push('DIALOG: ' + d.message()); await d.dismiss(); });

await page.goto(base, { waitUntil: 'load' });

// --- element contract
ok('form + inputs', await page.$('#note-form #title') && await page.$('#note-form #body') &&
  await page.$('#note-form #avatar') && await page.$('#note-form button[type=submit]'));
ok('search + results-line', !!(await page.$('#search')) && !!(await page.$('p#results-line')));
ok('results-line empty at rest', (await page.textContent('#results-line')) === '');
ok('6 seeded notes', (await page.$$('#feed article.note')).length === 6);
ok('note structure', await page.$('#feed article.note[data-note-id] .note-title') &&
  await page.$('#feed article.note .note-body'));
ok('avatars only where given', (await page.$$('#feed img.note-avatar')).length === 3,
  String((await page.$$('#feed img.note-avatar')).length));

// --- newest first
const order = await page.$$eval('#feed article.note', (n) => n.map((a) => a.dataset.noteId));
ok('newest first', order.join() === '6,5,4,3,2,1', order.join());

// --- rich text renders
ok('bold renders', !!(await page.$('#feed article[data-note-id="1"] .note-body b')));
ok('italic renders', !!(await page.$('#feed article[data-note-id="2"] .note-body i')));
ok('br renders', !!(await page.$('#feed article[data-note-id="3"] .note-body br')));
const href = await page.getAttribute('#feed article[data-note-id="4"] .note-body a', 'href');
ok('link renders + href kept', href === 'https://www.livrarialello.pt/', String(href));

// --- search
await page.fill('#search', 'douro');
await page.waitForTimeout(50);
ok('search filters (case-insensitive)', (await page.$$('#feed article.note')).length === 2,
  String((await page.$$('#feed article.note')).length));
ok('results line text', (await page.textContent('#results-line')) === 'results for "douro"',
