await page.waitForTimeout(50);
ok('aria-current set', (await page.getAttribute('#feed article[data-note-id="5"]', 'aria-current')) === 'true');
ok('combined fragment', page.url().endsWith('#q=douro&note=5'), page.url());
ok('only one selected', (await page.$$('#feed article.note[aria-current="true"]')).length === 1);

// --- clearing the query keeps the selection, drops q
await page.fill('#search', '');
await page.waitForTimeout(50);
ok('q dropped from fragment', page.url().endsWith('#note=5'), page.url());
ok('results-line cleared', (await page.textContent('#results-line')) === '');

