await page.goto(base + '#q=port&note=3', { waitUntil: 'load' });
await page.waitForTimeout(100);
ok('query restored', (await page.inputValue('#search')) === 'port');
ok('results line restored', (await page.textContent('#results-line')) === 'results for "port"');
ok('selection restored', (await page.getAttribute('#feed article[data-note-id="3"]', 'aria-current')) === 'true');
ok('fragment preserved', page.url().endsWith('#q=port&note=3'), page.url());

// --- hashchange (back/forward, manual edit)
await page.evaluate(() => { location.hash = '#note=2'; });
await page.waitForTimeout(80);
ok('hashchange adopted', (await page.inputValue('#search')) === '' &&
  (await page.getAttribute('#feed article[data-note-id="2"]', 'aria-current')) === 'true');

