ok('no dangerous nodes/attrs in feed', dangerous.length === 0, dangerous.join(' '));
const litText = await page.locator('#feed article.note').first().locator('.note-body').textContent();
ok('payload shown as text', litText.includes('<iframe'), JSON.stringify(litText));
ok('unclosed tag did not leak', (await page.$$('#feed .note-body b')).length >= 1);

// stored payload survives a reload without executing
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(200);
ok('no script after reload', (await page.evaluate(() => '__pwned' in window)) === false);

ok('no console/page errors', errors.length === 0, errors.join(' | '));

await browser.close();
server.kill();
console.log(`\n${pass} passed, ${fails.length} failed`);
for (const f of fails) console.log('  FAIL ' + f);
process.exit(fails.length ? 1 : 0);

